package net.civeira.phylax.features.access.userinvitation.domain.gateway;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class UserInvitationCursorUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_user_invitation_cursor_builder() {
    UserInvitationCursor cursor = UserInvitationCursor.builder().build();
    Assertions.assertFalse(cursor.getLimit().isPresent(),
        "Limit must be empty if cursor is build without it");
    Assertions.assertFalse(cursor.getSinceUid().isPresent(),
        "Since must be empty if cursor is build without it");
    cursor.setLimit(100);
    Assertions.assertEquals(100, cursor.getLimit().get(), "Limit must be the same as the assigned");
    cursor.setSinceUid("one");
    Assertions.assertEquals("one", cursor.getSinceUid().get(),
        "Since Uid must be the same as the assigned");
    Assertions.assertTrue(cursor.getOrder().isEmpty(), "The order must be empty");
    cursor.setOrder(List.of(UserInvitationOrder.CREATED_AT_DESC));
    Assertions.assertEquals(List.of(UserInvitationOrder.CREATED_AT_DESC), cursor.getOrder(),
        "The order must be the same that was assinged");
    Assertions.assertTrue(cursor.getSinceCreatedAt().isEmpty(),
        "The value since for CreatedAt must be empty");
    cursor.setSinceCreatedAt(null);
    Assertions.assertEquals(null, cursor.getSinceCreatedAt().get(),
        "The value since for CreatedAt must be the same that was assinged");
  }
}
